// CSV writing with RFC 4180 quoting and spreadsheet formula-injection neutralization for text cells.
const FORMULA = /^[=+\-@\t\r]/;

export function textCell(v: string | null | undefined): string {
  let s = v ?? '';
  if (FORMULA.test(s)) s = `'${s}`; // shown as text by Excel/LibreOffice/Sheets
  return /[",\r\n']/.test(s) || s !== s.trim() ? `"${s.replace(/"/g, '""')}"` : s;
}
/** Numeric cells are generated by us (exact decimals) and left unquoted so spreadsheets read numbers. */
export const numberCell = (v: string) => { if (!/^-?\d+(\.\d+)?$/.test(v)) throw new Error('not a number'); return v; };

export function toCsv(header: string[], rows: string[][]): string {
  // BOM so Excel opens UTF-8 (accents in Portuguese merchant names) correctly.
  return '﻿' + [header.map(textCell).join(','), ...rows.map((r) => r.join(','))].join('\r\n') + '\r\n';
}
